const KH_CATS = Object.keys(KQ);
const KH_TILE = [{ c: '#e21b3c', d: '#a8122b', s: '<path d="M12 3 22 21H2z"/>' }, { c: '#1368ce', d: '#0d4a96', s: '<path d="M12 1.5 22.5 12 12 22.5 1.5 12z"/>' }, { c: '#d89e00', d: '#a37600', s: '<circle cx="12" cy="12" r="10"/>' }, { c: '#26890c', d: '#1a6208', s: '<rect x="3" y="3" width="18" height="18" rx="1.5"/>' }];
